## Code Example
```cpp
uint32_t spread16(uint16_t v){
  uint32_t x = v;
  x = (x | (x << 8)) & 0x00FF00FF;
  x = (x | (x << 4)) & 0x0F0F0F0F;
  x = (x | (x << 2)) & 0x33333333;
  x = (x | (x << 1)) & 0x55555555;
  return x;
}
uint32_t interleave16(uint16_t a, uint16_t b){
  return spread16(a) | (spread16(b) << 1);
}
```

